  gorsel: "<svg viewBox=\"0 0 300 165\" role=\"img\" aria-label=\"Taban çapı 6 cm, yüksekliği 9 cm olan silindir\"><path d=\"M120,40 L120,130 A30,10 0 0 0 180,130 L180,40 Z\" fill=\"var(--dolgu)\"/><path d=\"M120,40 L120,130 A30,10 0 0 0 180,130 L180,40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M120,130 A30,10 0 0 1 180,130\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/><ellipse cx=\"150\" cy=\"40\" rx=\"30\" ry=\"10\" fill=\"var(--dolgu)\" fill-opacity=\"1\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"120\" y1=\"40\" x2=\"180\" y2=\"40\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\"/><circle cx=\"120\" cy=\"40\" r=\"3.5\" fill=\"var(--vurgu)\"/><circle cx=\"180\" cy=\"40\" r=\"3.5\" fill=\"var(--vurgu)\"/><text x=\"150\" y=\"20\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-weight=\"700\">6 cm</text><line x1=\"102\" y1=\"40\" x2=\"102\" y2=\"130\" stroke=\"var(--vurgu2)\" stroke-width=\"2\"/><line x1=\"97\" y1=\"40\" x2=\"107\" y2=\"40\" stroke=\"var(--vurgu2)\" stroke-width=\"2\"/><line x1=\"97\" y1=\"130\" x2=\"107\" y2=\"130\" stroke=\"var(--vurgu2)\" stroke-width=\"2\"/><text x=\"93\" y=\"90\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"end\" font-weight=\"700\">9 cm</text></svg>",
  secenekler: ["15","9","6","3"],
